import { useEffect, useState } from 'react';

/** Текущий путь из хэша: `#/tasks` → `/tasks`, пустой хэш → `/`. */
function readPath(): string {
  const path = window.location.hash.replace(/^#/, '');
  return path.startsWith('/') ? path : '/';
}

/**
 * Минимальный хэш-роутер: без зависимостей, работает на любом статическом
 * хостинге, кнопки «назад/вперёд» браузера поддерживаются из коробки.
 */
export function useHashRoute(): string {
  const [path, setPath] = useState(readPath);

  useEffect(() => {
    const onChange = () => {
      setPath(readPath());
      window.scrollTo(0, 0);
    };
    window.addEventListener('hashchange', onChange);
    return () => window.removeEventListener('hashchange', onChange);
  }, []);

  return path;
}
EOF
cat > useStoredTheme.ts <<'EOF'
import { useEffect, useState } from 'react';

export type AppTheme = 'light' | 'dark';

const STORAGE_KEY = 'app-theme';

function getInitialTheme(): AppTheme {
  try {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved === 'light' || saved === 'dark') return saved;
  } catch {
    // localStorage может быть недоступен (приватный режим и т.п.)
  }
  return window.matchMedia?.('(prefers-color-scheme: dark)').matches ? 'dark' : 'light';
}

/** Тема с сохранением выбора пользователя; по умолчанию — системная. */
export function useStoredTheme() {
  const [theme, setTheme] = useState<AppTheme>(getInitialTheme);

  useEffect(() => {
    try {
      localStorage.setItem(STORAGE_KEY, theme);
    } catch {
      // не критично — просто не запомним выбор
    }
  }, [theme]);

  return [theme, setTheme] as const;
}
EOF
